BEGIN;

-- Identify untouched generated templates using the exact criteria from migration 623.
CREATE TEMP TABLE interview_criteria_refresh ON COMMIT DROP AS
SELECT name, (SELECT jsonb_agg(jsonb_build_object('name', topic, 'max_score', 10) ORDER BY seq)
  FROM unnest(string_to_array('ความเข้าใจหน้าที่และผลงานที่ต้องส่งมอบ|ตัวอย่างความรับผิดชอบและการทำงานให้เสร็จตามกำหนด|การสื่อสารและทำงานร่วมกับผู้อื่น|การแก้ปัญหาจากสถานการณ์งานจริง|การเรียนรู้จากข้อผิดพลาดและรับคำแนะนำ|' || topics, '|')) WITH ORDINALITY AS items(topic, seq)) AS previous_criteria
FROM (VALUES
 ('มาตรฐาน — พนักงานปฏิบัติการ', 'การทำตามขั้นตอนและคำสั่งงาน|ความละเอียดและตรวจสอบคุณภาพ|ความรู้ความปลอดภัยในการทำงาน|การจัดลำดับงานและบริหารเวลา|ทักษะพื้นฐานจากแบบทดสอบที่เกี่ยวกับงาน'),
 ('มาตรฐาน — เจ้าหน้าที่', 'ความรู้เฉพาะหน้าที่จากตัวอย่างงาน|ความถูกต้องของเอกสารและข้อมูล|การใช้เครื่องมือหรือระบบที่เกี่ยวข้อง|การประสานงานและติดตามผล|การวางแผนงานด้วยตนเอง'),
 ('มาตรฐาน — ผู้เชี่ยวชาญ / อาวุโส', 'ความลึกของความรู้เฉพาะทาง|การวิเคราะห์ปัญหาซับซ้อน|การออกแบบวิธีทำงานและมาตรฐาน|การสอนงานและถ่ายทอดความรู้|ผลลัพธ์การปรับปรุงงานที่วัดได้'),
 ('มาตรฐาน — หัวหน้างาน', 'การวางแผนกำลังคนและจัดสรรงาน|การควบคุมคุณภาพและติดตามเป้าหมาย|การสอนงานและให้ข้อเสนอแนะ|การจัดการความขัดแย้งในทีม|การตัดสินใจและรับผิดชอบผลลัพธ์'),
 ('มาตรฐาน — ผู้จัดการ', 'การแปลงเป้าหมายเป็นแผนและตัวชี้วัด|การบริหารงบประมาณและทรัพยากร|การพัฒนาทีมและผู้สืบทอด|การบริหารความเสี่ยงและการควบคุมภายใน|การประสานงานระหว่างหน่วยงาน'),
 ('มาตรฐาน — ผู้บริหาร', 'วิสัยทัศน์และการวางกลยุทธ์ธุรกิจ|การวิเคราะห์การเงินและตัดสินใจลงทุน|การบริหารการเปลี่ยนแปลงองค์กร|ธรรมาภิบาลและการจัดการความเสี่ยง|การสร้างทีมผู้นำและติดตามผลระดับองค์กร'),
 ('มาตรฐาน — คลังสินค้า / จัดส่ง', 'การรับเข้าและตรวจนับสินค้า|การหยิบแพ็กและตรวจสอบคำสั่งซื้อ|ความเข้าใจสต๊อกและการตรวจสอบยอด|การใช้ระบบคลังและเอกสารขนส่ง|ความปลอดภัยและการดูแลสินค้า'),
 ('มาตรฐาน — ผลิต / ควบคุมคุณภาพ', 'ความเข้าใจกระบวนการผลิต|การใช้เครื่องมือและตรวจงานตัวอย่าง|การตรวจพบข้อบกพร่องและป้องกันงานเสีย|การรักษามาตรฐานคุณภาพและความปลอดภัย|การปรับปรุงประสิทธิภาพและลดของเสีย'),
 ('มาตรฐาน — ออกแบบ / สร้างสรรค์', 'คุณภาพ Portfolio และบทบาทในผลงาน|การตีความโจทย์และข้อจำกัด|ทักษะเครื่องมือจากงานทดลอง|การเตรียมไฟล์และตรวจความพร้อมผลิต|การรับข้อเสนอแนะและแก้งานตามกำหนด'),
 ('มาตรฐาน — ขาย / บริการลูกค้า', 'การค้นหาความต้องการและให้ข้อมูลสินค้า|การเสนอขายและเจรจาต่อรอง|การรับข้อร้องเรียนอย่างเหมาะสม|การติดตามลูกค้าและบันทึกข้อมูล|ผลงานขายหรือบริการที่ตรวจสอบได้'),
 ('มาตรฐาน — บัญชี / การเงิน', 'ความเข้าใจเอกสารและรายการบัญชี|การตรวจสอบและกระทบยอด|การวิเคราะห์ตัวเลขและค้นหาความผิดปกติ|การใช้ระบบบัญชีและตารางคำนวณ|การรักษาความลับและการควบคุมภายใน'),
 ('มาตรฐาน — HR / ธุรการ', 'ความถูกต้องของเอกสารและข้อมูลบุคลากร|การประสานงานและบริการภายใน|การใช้ระบบและจัดการเอกสาร|การจัดการข้อมูลส่วนบุคคลตามหน้าที่|การแก้สถานการณ์งานบุคคลหรือธุรการ'),
 ('มาตรฐาน — IT / พัฒนาระบบ', 'ความรู้ระบบหรือเทคโนโลยีที่ใช้ในงาน|การวิเคราะห์และแก้ปัญหาจากโจทย์จริง|การทดสอบและดูแลคุณภาพระบบ|ความปลอดภัยและการจัดการสิทธิ์ข้อมูล|การอธิบายงานเทคนิคและจัดทำเอกสาร'),
 ('มาตรฐาน — จัดซื้อ', 'การเปรียบเทียบราคาและต้นทุนรวม|การประเมินและติดตามผู้ขาย|การเจรจาและเงื่อนไขจัดซื้อ|ความถูกต้องของเอกสารและการอนุมัติ|การวางแผนจัดหาและจัดการความเสี่ยง')
) AS presets(name, topics);
ALTER TABLE interview_criteria_refresh ADD COLUMN updated_criteria JSONB;

-- Score answers, prior examples (including study or volunteer work), and short
-- interview exercises. Do not require experience at this company.
UPDATE interview_criteria_refresh old SET updated_criteria = (
  SELECT jsonb_agg(jsonb_build_object('name', topic, 'max_score', 10) ORDER BY seq)
  FROM unnest(string_to_array(
    'อธิบายความเข้าใจตำแหน่งที่สมัครและเหตุผลที่สนใจงานนี้|เล่าตัวอย่างการรับผิดชอบงานหรือโครงงานที่ผ่านมา พร้อมอธิบายบทบาทของตนเอง|ตอบคำถามจำลองเมื่อต้องร่วมงานกับคนที่มีความคิดเห็นต่างกัน|อธิบายวิธีแก้โจทย์ปัญหาที่ผู้สัมภาษณ์กำหนดและเหตุผลที่เลือกวิธีนั้น|เล่าตัวอย่างการเรียนรู้สิ่งใหม่หรือรับคำแนะนำแล้วนำไปปรับใช้ (ใช้ตัวอย่างจากการเรียนได้)|' || revised.topics, '|'))
    WITH ORDINALITY AS items(topic, seq)
)
FROM (VALUES
 ('มาตรฐาน — พนักงานปฏิบัติการ', 'ทดลองทำตามคำสั่งงานสั้น ๆ แล้วอธิบายขั้นตอนที่เข้าใจ|ทดลองตรวจชิ้นงานหรือรายการตัวอย่างเพื่อหาจุดผิดพลาด|ตอบสถานการณ์จำลองเมื่อพบอุปกรณ์หรือวิธีทำงานที่ไม่ปลอดภัย|จัดลำดับงานตัวอย่าง 3 งาน พร้อมอธิบายเหตุผล|ทดลองอ่านใบงาน นับจำนวน หรือคำนวณพื้นฐานที่เกี่ยวข้องกับตำแหน่ง'),
 ('มาตรฐาน — เจ้าหน้าที่', 'อธิบายความรู้พื้นฐานที่จำเป็นต่อหน้าที่จากคำถามสัมภาษณ์|ทดลองตรวจเอกสารหรือข้อมูลตัวอย่างและระบุข้อผิดพลาด|สาธิตการใช้เครื่องมือสำนักงานหรือระบบที่เกี่ยวข้องจากโจทย์สั้น ๆ|ตอบสถานการณ์จำลองเมื่อต้องติดตามงานจากอีกหน่วยงาน|วางแผนทำงานจากโจทย์ที่มีเส้นตายและข้อจำกัดที่กำหนด'),
 ('มาตรฐาน — ผู้เชี่ยวชาญ / อาวุโส', 'อธิบายแนวคิดเฉพาะทางและเหตุผลเบื้องหลังวิธีที่เลือก|วิเคราะห์กรณีศึกษาที่ซับซ้อน พร้อมระบุข้อมูลที่ต้องขอเพิ่ม|เสนอวิธีหรือมาตรฐานสำหรับโจทย์งานตัวอย่าง พร้อมข้อดีและข้อจำกัด|ทดลองอธิบายเรื่องเฉพาะทางให้ผู้เริ่มต้นเข้าใจ|เล่าผลงานที่ผ่านมาโดยแยกบทบาทตนเอง ผลลัพธ์ และบทเรียนที่ได้'),
 ('มาตรฐาน — หัวหน้างาน', 'จัดสรรงานจากโจทย์ทีมที่กำลังคนไม่พอ พร้อมอธิบายเหตุผล|เสนอวิธีติดตามคุณภาพและความคืบหน้าจากสถานการณ์จำลอง|จำลองการให้คำแนะนำลูกทีมที่ทำงานผิดพลาด|ตอบกรณีความขัดแย้งของลูกทีมโดยเสนอขั้นตอนจัดการ|ตัดสินใจจากกรณีงานเร่งด่วนและอธิบายความเสี่ยงที่ยอมรับได้'),
 ('มาตรฐาน — ผู้จัดการ', 'เสนอแผนงานและตัวชี้วัดจากเป้าหมายธุรกิจตัวอย่าง|จัดสรรงบประมาณจากโจทย์จำลอง พร้อมอธิบายสิ่งที่เลือกตัดหรือเพิ่ม|เล่าประสบการณ์พัฒนาทีมหรือเสนอวิธีพัฒนาทีมจากกรณีศึกษา|ระบุความเสี่ยงและวิธีควบคุมจากกรณีหน่วยงานตัวอย่าง|ตอบสถานการณ์ที่สองแผนกมีเป้าหมายขัดกันและเสนอวิธีหาข้อตกลง'),
 ('มาตรฐาน — ผู้บริหาร', 'วิเคราะห์กรณีธุรกิจและเสนอทิศทางกลยุทธ์พร้อมสมมติฐาน|อ่านข้อมูลการเงินตัวอย่างและอธิบายเหตุผลในการตัดสินใจลงทุน|เสนอแผนเปลี่ยนแปลงองค์กรจากกรณีศึกษาพร้อมวิธีรับมือแรงต้าน|ตอบโจทย์ความขัดแย้งทางผลประโยชน์และความเสี่ยงระดับองค์กร|เล่าบทบาทในการนำองค์กรที่ผ่านมา พร้อมผลลัพธ์ที่ตรวจสอบได้และบทเรียน'),
 ('มาตรฐาน — คลังสินค้า / จัดส่ง', 'ทดลองอ่านใบรับสินค้าแล้วตรวจนับจำนวนจากตัวอย่าง|ทดลองจับคู่ใบสั่งซื้อกับสินค้าและเสนอวิธีแพ็กที่เหมาะสม|คำนวณยอดคงเหลือจากรายการรับเข้าและจ่ายออกตัวอย่าง|อธิบายหรือสาธิตขั้นตอนบันทึกรับเข้าและจัดส่งจากโจทย์จำลอง|ตอบสถานการณ์สินค้าเสียหาย ของไม่ครบ หรือพื้นที่จัดเก็บไม่ปลอดภัย'),
 ('มาตรฐาน — ผลิต / ควบคุมคุณภาพ', 'อธิบายลำดับผลิตจากใบงานหรือตัวอย่างที่ผู้สัมภาษณ์ให้|สาธิตหรืออธิบายการเลือกเครื่องมือสำหรับโจทย์ทดลอง|ตรวจชิ้นงานตัวอย่างและอธิบายเกณฑ์แยกงานดีกับงานเสีย|ตอบสถานการณ์ที่ต้องเลือกระหว่างเร่งผลิตกับความปลอดภัยหรือคุณภาพ|เสนอวิธีลดงานเสียจากกรณีศึกษาสั้น ๆ พร้อมอธิบายเหตุผล'),
 ('มาตรฐาน — ออกแบบ / สร้างสรรค์', 'นำเสนอ Portfolio พร้อมอธิบายโจทย์ บทบาทตนเอง และเหตุผลการออกแบบ|ตีความ Brief ตัวอย่างและถามข้อมูลที่ยังขาดก่อนเริ่มงาน|ทดลองออกแบบหรือแก้ไฟล์จากโจทย์สั้นที่ใช้เครื่องมือของตำแหน่ง|ตรวจไฟล์ตัวอย่างและระบุปัญหาที่อาจเกิดก่อนส่งผลิต|ตอบสถานการณ์ลูกค้าขอแก้งานใกล้เส้นตายและเสนอวิธีจัดการ'),
 ('มาตรฐาน — ขาย / บริการลูกค้า', 'จำลองการถามความต้องการลูกค้าจากข้อมูลสินค้าตัวอย่าง|ทดลองเสนอสินค้าหรือรับมือข้อโต้แย้งในการขาย|จำลองการตอบลูกค้าที่ร้องเรียนหรือไม่พอใจ|เสนอวิธีติดตามลูกค้าและทดลองบันทึกข้อมูลจากบทสนทนาตัวอย่าง|เล่าประสบการณ์ขายหรือบริการ หรือวิเคราะห์กรณีลูกค้าเมื่อยังไม่มีประสบการณ์'),
 ('มาตรฐาน — บัญชี / การเงิน', 'ตอบคำถามพื้นฐานและจับคู่เอกสารกับรายการบัญชีตัวอย่าง|ทดลองกระทบยอดข้อมูลสองชุดและอธิบายส่วนต่าง|อ่านตารางตัวเลขตัวอย่างเพื่อหาความผิดปกติและตั้งคำถาม|ทดลองใช้ตารางคำนวณหรืออธิบายขั้นตอนบันทึกบัญชีจากโจทย์สั้น|ตอบสถานการณ์พบเอกสารไม่ครบหรือถูกขอให้เปิดเผยข้อมูลการเงิน'),
 ('มาตรฐาน — HR / ธุรการ', 'ทดลองตรวจเอกสารสมัครงานหรือเอกสารธุรการตัวอย่างเพื่อหาข้อมูลที่ขาด|จำลองการตอบคำถามผู้สมัครหรือผู้ขอรับบริการภายใน|ทดลองจัดหมวดเอกสารหรือบันทึกข้อมูลจากโจทย์สำนักงาน|ตอบสถานการณ์มีผู้ขอดูข้อมูลบุคลากรที่ไม่เกี่ยวกับหน้าที่|เสนอขั้นตอนจัดการกรณีนัดหมายซ้ำ เอกสารผิด หรือผู้สมัครเลื่อนนัด'),
 ('มาตรฐาน — IT / พัฒนาระบบ', 'อธิบายเทคโนโลยีที่เกี่ยวข้องและเลือกแนวทางสำหรับโจทย์ตัวอย่าง|ทดลองแก้บั๊ก เขียนโปรแกรมสั้น หรือวิเคราะห์เหตุขัดข้องตามตำแหน่ง|ออกแบบกรณีทดสอบสำหรับงานตัวอย่างและอธิบายสิ่งที่ต้องตรวจ|ตอบสถานการณ์บัญชีผู้ใช้ถูกเข้าถึงผิดปกติหรือสิทธิ์ข้อมูลไม่เหมาะสม|ทดลองอธิบายปัญหาเทคนิคและแนวทางแก้ให้ผู้ใช้ทั่วไปเข้าใจ'),
 ('มาตรฐาน — จัดซื้อ', 'เปรียบเทียบใบเสนอราคาตัวอย่างโดยคำนวณต้นทุนรวม|เสนอวิธีเลือกผู้ขายจากข้อมูลคุณภาพ ราคา และกำหนดส่งที่ให้|จำลองการเจรจาราคา เงื่อนไขชำระเงิน หรือกำหนดส่ง|ตรวจเอกสารจัดซื้อตัวอย่างและระบุข้อมูลหรือการอนุมัติที่ขาด|ตอบสถานการณ์ผู้ขายส่งของล่าช้าหรือเสนอผลประโยชน์ส่วนตัว')
) AS revised(name, topics)
WHERE old.name = revised.name;

-- Refresh only untouched standard sets and generated per-position copies.
-- Custom sets, edited criteria, assignments and recorded interview scores stay intact.
UPDATE public.hr_interview_template_sets t SET criteria = r.updated_criteria
FROM interview_criteria_refresh r
WHERE r.updated_criteria IS NOT NULL AND t.criteria = r.previous_criteria
  AND (t.name = r.name OR t.name LIKE 'ตำแหน่ง — %');
COMMIT;
